let mut beats = Vec::new();
let mut chars = music_string.chars().peekable();

while let Some(&c) = chars.peek() {
    match c {
        'o' => {
            // Check if it's a half note 'o|' or whole note 'o'
            chars.next(); // consume 'o'
            if chars.peek() == Some(&'|') {
                beats.push(2);
                chars.next(); // consume '|'
            } else {
                beats.push(4);
            }
        },
        '.' => {
            // It's a quarter note '.|'
            chars.next(); // consume '.'
            if chars.peek() == Some(&'|') {
                beats.push(1);
                chars.next(); // consume '|'
            } else {
                // This case should not happen based on the problem description
                panic!("Invalid input format");
            }
        },
        ' ' => {
            // Skip spaces
            chars.next();
        },
        _ => {
            // Invalid character
            panic!("Invalid input format");
        }
    }
}

